Terumos uMa'asros — Halacha Three, Part One

:root{--parchment:#f5ead6;--ink:#2c1a0e;--red:#8b1a1a;--gold:#8b6914;--border:#c4a45a;}

*{box-sizing:border-box;margin:0;padding:0;}

body{background:#3a2a18;font-family:'EB Garamond',Georgia,serif;color:var(--ink);padding:40px 20px;}

.page{max-width:820px;margin:0 auto;background:var(--parchment);border:2px solid var(--border);border-radius:4px;box-shadow:0 8px 40px rgba(44,26,14,.18);padding:60px 70px;}

.sl{text-align:center;font-family:'Cinzel',serif;font-size:12px;letter-spacing:3px;text-transform:uppercase;color:var(--gold);margin-bottom:10px;}

.mt{text-align:center;font-family:'Cinzel Decorative',serif;font-size:24px;color:var(--red);margin-bottom:6px;}

.st{text-align:center;font-family:'Cinzel',serif;font-size:14px;color:var(--gold);margin-bottom:6px;}

.dv{text-align:center;color:var(--border);font-size:20px;margin:18px 0;letter-spacing:8px;}

.cr{font-family:'Cinzel',serif;font-size:11.5px;color:var(--gold);text-align:center;margin-bottom:20px;}

.sn-box{background:#f0e0c0;border:1px solid var(--border);border-radius:3px;padding:12px 18px;margin:28px 0 20px;font-family:'Cinzel',serif;font-size:11px;color:var(--gold);text-align:center;}

.sh{font-family:'Cinzel',serif;font-size:13px;color:var(--red);margin:32px 0 10px;padding-bottom:6px;border-bottom:1px solid var(--border);text-align:center;}

p{font-size:17px;line-height:1.9;margin-bottom:16px;text-align:justify;text-indent:2em;}

p.ni{text-indent:0;}

em{font-style:italic;color:#4a2a10;}

.sn{font-family:'Cinzel',serif;font-size:11px;color:var(--gold);border-top:1px solid var(--border);margin-top:40px;padding-top:14px;text-align:center;}

@media(max-width:600px){.page{padding:36px 22px;}.mt{font-size:18px;}p{font-size:15.5px;}}

